	let size = Number(String(java.getString("$.info[*].size")));
	let url = jiexi(path,size);
	result = url.url+","+JSON.stringify({
		headers:url.header,
		type:a
		})
	}
}else{
	result = 'data:url;base64,,{"type":""}'
	}
</js>

